{"code":"# Parse processed_spectrum.dx and compute simple window metrics around target and main peak
from pathlib import Path
import re, statistics, math
p=Path('raw_spectra/R0044/raw_data_analysis/sample_20260724_185954/processed_spectrum.dx')
lines=p.read_text(errors='replace').splitlines()
start=next(i+1 for i,l in enumerate(lines) if l.startswith('##DATA TABLE=') and 'XYDATA' in l)
end=next((j for j in range(start,len(lines)) if lines[j].startswith('##PAGE=N=2') or lines[j].startswith('##END')), len(lines))
header='\n'.join(lines[:start])
first=float(re.search(r'##FIRST=\s*([^,]+)',header).group(1)); last=float(re.search(r'##LAST=\s*([^,]+)',header).group(1)); dim=int(re.search(r'##VAR_DIM=\s*(\d+)',header).group(1))
dx=(last-first)/(dim-1)
xs=[]; ys=[]; idx=0
for l in lines[start:end]:
    if l.startswith('#') or not l.strip(): continue
    vals=[]
    for tok in l.split():
        try: vals.append(float(tok))
        except: pass
    for y in vals[1:]:
        if idx<dim:
            xs.append(first+idx*dx); ys.append(y); idx+=1
med=statistics.median(ys)
# integrate positive-above-median in windows (rough)
def metrics(center,width):
    lo=center-width; hi=center+width
    pts=[(x,y) for x,y in zip(xs,ys) if lo<=x<=hi]
    pos_area=sum(max(0,y-med) for x,y in pts)*abs(dx)
    signed_area=sum((y-med) for x,y in pts)*abs(dx)
    maxpt=max(pts,key=lambda t:t[1]); minpt=min(pts,key=lambda t:t[1])
    return {'lo':lo,'hi':hi,'n':len(pts),'maxppm':maxpt[0],'maxamp':maxpt[1],'minppm':minpt[0],'minamp':minpt[1],'pos_area':pos_area,'signed_area':signed_area}
for c,w,name in [(-58,0.1,'target +/-0.1'),(-58,0.2,'target +/-0.2'),(-58,3,'target +/-3'),(-76.466,0.1,'main +/-0.1'),(-76.466,0.2,'main +/-0.2')]:
    print(name, metrics(c,w))
print('target/main area ratio +/-0.2:', metrics(-58,0.2)['pos_area']/metrics(-76.466,0.2)['pos_area'])","timeout_seconds":10}

